/* Minimal jQuery shim used as offline fallback for UI pages in tests.
   This is not the full jQuery implementation. It only provides a few globals
   so templates that expect jQuery won't immediately fail when CDN is blocked.
*/
window.jQuery = window.$ = function(selector) { return document.querySelectorAll(selector || null); };
window.jQuery.fn = window.jQuery.prototype = {};
// basic ready handler
window.jQuery.ready = function(fn){ if (document.readyState !== 'loading') { fn(); } else { document.addEventListener('DOMContentLoaded', fn); } };
// minimal ajax stub (no-op)
window.jQuery.ajax = function() { return { done: function(){}, fail: function(){}, always: function(){} }; };

// mark version
window.jQuery.fn.jquery = '3.6.0-fallback';
